import type { SupabaseClient } from "@supabase/supabase-js";

import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Status } from "@/components/ui/status";
import { approveProductionDevelopmentSummary, correctProductionMatchEvent, createProductionDevelopmentObjective, createProductionDevelopmentReview, createProductionDrill, createProductionMatchDay, createProductionTrainingTemplate, recordProductionMatchEvent, recordProductionObservation, recordProductionPlayingTimeCorrection, rotateProductionPositions, saveProductionFormation, saveProductionMatchReflection, substituteProductionPlayer, transitionProductionMatch } from "@/features/coaching/actions";
import { ProductionAttendanceRecorder } from "@/features/screens/coach/production-attendance-recorder";
import { ProductionAiSuggestion } from "@/features/screens/coach/production-ai-suggestion";
import { ProductionMatchClock } from "@/features/screens/coach/production-match-clock";
import { ProductionPlayingTimeTracker } from "@/features/screens/coach/production-playing-time-tracker";
import { ProductionTrainingBuilder } from "@/features/screens/coach/production-training-builder";
import { createServerSupabaseClient } from "@/lib/supabase/server";

const panel = "rounded-2xl border border-border-strong bg-background p-5 sm:p-7";
const field = "mt-2 min-h-11 w-full rounded-[10px] border border-border-strong bg-background px-3";
type Row = Record<string, unknown>;
type PlayerOption = { id: string; label: string };
type MatchEventOption = { id: string; title: string; startsAt: string };

function Context({ workspace, section }: { workspace: string; section: string }) { return <><input type="hidden" name="workspace" value={workspace}/><input type="hidden" name="section" value={section}/></>; }
function Value({ value }: { value: unknown }) { return <span>{value == null ? "—" : String(value).replaceAll("_", " ")}</span>; }
function Records({ title, rows, limit = 4 }: { title: string; rows: readonly Row[]; limit?: number }) { return <section className={panel}><h2 className="text-xl font-semibold text-ink">{title}</h2><ul className="mt-4 divide-y divide-border">{rows.map((row, index) => <li className="grid gap-1 py-3 text-sm sm:grid-cols-2" key={String(row.id ?? index)}>{Object.entries(row).filter(([key]) => !key.endsWith("_id") && key !== "id").slice(0, limit).map(([key, value]) => <span key={key}><strong className="mr-2 capitalize text-ink">{key.replaceAll("_", " ")}:</strong><Value value={value}/></span>)}</li>)}</ul></section>; }
const observationFields = [
  ["observation", "Observation"], ["context", "Context"], ["strength", "Strength"],
  ["emerging_skill", "Emerging skill"], ["opportunity", "Opportunity"],
  ["confidence_engagement", "Confidence and engagement"], ["position_code", "Position"],
  ["next_action", "Next action"], ["training_theme", "Training theme"],
  ["visibility", "Visibility"], ["follow_up_date", "Follow-up date"],
] as const;
function ObservationRecords({ rows, players }: { rows: readonly Row[]; players: readonly PlayerOption[] }) {
  const playerLabels = new Map(players.map((player) => [player.id, player.label]));
  return <section className={panel}><h2 className="text-xl font-semibold text-ink">Audited private observations</h2><ul className="mt-4 divide-y divide-border">{rows.map((row, index) => <li className="py-4 text-sm" key={String(row.id ?? index)}><p><strong className="text-ink">Player:</strong> {playerLabels.get(String(row.player_id)) ?? "Player record"}</p><dl className="mt-3 grid gap-3 sm:grid-cols-2">{observationFields.map(([key, label]) => <div key={key}><dt className="font-semibold text-ink">{label}</dt><dd className="mt-1 text-muted"><Value value={row[key]}/></dd></div>)}</dl></li>)}</ul></section>;
}
function MatchDayCreator({ events, workspace, section, another = false }: { events: readonly MatchEventOption[]; workspace: string; section: string; another?: boolean }) {
  if (!events.length) return null;
  return <section className={panel}><h2 className="text-xl font-semibold text-ink">{another ? "Create another match day" : "Create match day"}</h2><p className="mt-2 text-sm text-muted">Choose a canonical scheduled match and the competition side size. The match record is created atomically.</p><form action={createProductionMatchDay} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><label className="text-sm font-semibold">Match event<select className={field} name="eventInstanceId">{events.map((event) => <option key={event.id} value={event.id}>{event.title} · {new Date(event.startsAt).toLocaleString("en-GB")}</option>)}</select></label><label className="text-sm font-semibold">Side size<select className={field} name="sideSize" defaultValue="7">{Array.from({ length: 7 }, (_, index) => index + 5).map((size) => <option key={size} value={size}>{size}-a-side</option>)}</select></label><Button className="sm:col-span-2" type="submit">{another ? "Create another match day" : "Create match day"}</Button></form></section>;
}
function ScopeSelector({ name, value, options, label }: { name: "teamId"|"matchId"|"sessionId"; value?: string; options: { id: string; label: string }[]; label: string }) { return <form method="get" className={`${panel} flex flex-wrap items-end gap-3`}><label className="grow text-sm font-semibold">{label}<select className={field} name={name} defaultValue={value}>{options.map((option) => <option key={option.id} value={option.id}>{option.label}</option>)}</select></label><Button type="submit" variant="secondary">Open</Button></form>; }
async function loadTeamPlayers(db: SupabaseClient, organisationId: string, teamId: string): Promise<PlayerOption[]> {
  const { data: membershipData, error: membershipError } = await db.from("team_memberships").select("player_id").eq("organisation_id", organisationId).eq("team_id", teamId).eq("member_kind", "player").eq("status", "active").order("id").limit(250);
  if (membershipError) throw new Error("We could not load the team roster.");
  const ids = (membershipData ?? []).flatMap((row) => typeof row.player_id === "string" ? [row.player_id] : []);
  if (!ids.length) return [];
  const { data: playerData, error: playerError } = await db.from("players").select("id,first_name,last_name").eq("organisation_id", organisationId).in("id", ids).order("first_name").limit(250);
  if (playerError) throw new Error("We could not load the team roster.");
  return (playerData ?? []).map((row) => ({ id: String(row.id), label: `${String(row.first_name)} ${String(row.last_name)}` }));
}
async function loadMatchPlayers(db: SupabaseClient, organisationId: string, eventInstanceId: string, teamId: string): Promise<{ players: PlayerOption[]; source: "Published squad" | "Active roster" }> {
  const { data: squad, error: squadError } = await db.from("squads").select("id").eq("organisation_id", organisationId).eq("event_instance_id", eventInstanceId).eq("status", "published").maybeSingle();
  if (squadError) throw new Error("We could not load the published squad.");
  if (!squad) return { players: await loadTeamPlayers(db, organisationId, teamId), source: "Active roster" };
  const { data: members, error: membersError } = await db.from("squad_members").select("player_id").eq("organisation_id", organisationId).eq("squad_id", String(squad.id)).eq("status", "selected").order("position_order").limit(100);
  if (membersError) throw new Error("We could not load the published squad members.");
  const playerIds = (members ?? []).map((member) => String(member.player_id));
  if (!playerIds.length) return { players: [], source: "Published squad" };
  const { data: playerData, error: playerError } = await db.from("players").select("id,first_name,last_name").eq("organisation_id", organisationId).in("id", playerIds).order("id").limit(100);
  if (playerError) throw new Error("We could not load the published squad players.");
  const labels = new Map((playerData ?? []).map((player) => [String(player.id), `${String(player.first_name)} ${String(player.last_name)}`]));
  return { players: playerIds.flatMap((id) => labels.has(id) ? [{ id, label: labels.get(id)! }] : []), source: "Published squad" };
}

export async function ProductionCoachingScopeSelector({ organisationId, section, selection = {} }: { organisationId: string; section: string; selection?: { teamId?: string; matchId?: string; sessionId?: string } }) {
  const client = await createServerSupabaseClient(); if (!client) return null; const db = client as unknown as SupabaseClient;
  if (["match-day","formation","playing-time"].includes(section)) {
    const { data } = await db.from("matches").select("id,team_id,event_instance_id,state").eq("organisation_id",organisationId).order("created_at",{ ascending:false }).limit(100);
    if (!data?.length) return null;
    const teamIds = [...new Set(data.map((item) => String(item.team_id)))];
    const instanceIds = data.map((item) => String(item.event_instance_id));
    const { data: teams } = await db.from("teams").select("id,name").eq("organisation_id",organisationId).in("id",teamIds).limit(100);
    const { data: instances } = await db.from("event_instances").select("id,event_id,starts_at").eq("organisation_id",organisationId).in("id",instanceIds).limit(100);
    const eventIds = (instances ?? []).map((item) => String(item.event_id));
    const { data: events } = eventIds.length ? await db.from("events").select("id,title").eq("organisation_id",organisationId).in("id",eventIds) : { data: [] };
    const teamNames = new Map((teams ?? []).map((team) => [String(team.id),String(team.name)]));
    const instanceById = new Map((instances ?? []).map((instance) => [String(instance.id),instance]));
    const eventNames = new Map((events ?? []).map((event) => [String(event.id),String(event.title)]));
    return <ScopeSelector name="matchId" value={selection.matchId} label="Choose match" options={data.map((item) => { const instance = instanceById.get(String(item.event_instance_id)); return { id:String(item.id),label:`${teamNames.get(String(item.team_id)) ?? "Team"} · ${eventNames.get(String(instance?.event_id)) ?? "Match"} · ${instance?.starts_at ? new Date(String(instance.starts_at)).toLocaleDateString("en-GB") : "Date pending"} · ${String(item.state)}` }; })}/>;
  }
  if (["training","attendance"].includes(section)) {
    const { data } = await db.from("training_sessions").select("id,team_id,event_instance_id,title").eq("organisation_id",organisationId).order("created_at",{ ascending:false }).limit(100);
    if (!data?.length) return null;
    const teamIds = [...new Set(data.map((item) => String(item.team_id)))];
    const instanceIds = data.map((item) => String(item.event_instance_id));
    const { data: teams } = await db.from("teams").select("id,name").eq("organisation_id",organisationId).in("id",teamIds).limit(100);
    const { data: instances } = await db.from("event_instances").select("id,event_id,starts_at").eq("organisation_id",organisationId).in("id",instanceIds).limit(100);
    const eventIds = (instances ?? []).map((item) => String(item.event_id));
    const { data: events } = eventIds.length ? await db.from("events").select("id,title").eq("organisation_id",organisationId).in("id",eventIds) : { data: [] };
    const teamNames = new Map((teams ?? []).map((team) => [String(team.id),String(team.name)]));
    const instanceById = new Map((instances ?? []).map((instance) => [String(instance.id),instance]));
    const eventNames = new Map((events ?? []).map((event) => [String(event.id),String(event.title)]));
    return <ScopeSelector name="sessionId" value={selection.sessionId} label="Choose training session" options={data.map((item) => { const instance = instanceById.get(String(item.event_instance_id)); return { id:String(item.id),label:`${teamNames.get(String(item.team_id)) ?? "Team"} · ${eventNames.get(String(instance?.event_id)) ?? String(item.title)} · ${instance?.starts_at ? new Date(String(instance.starts_at)).toLocaleDateString("en-GB") : "Date pending"}` }; })}/>;
  }
  if (["players","development"].includes(section)) { const { data } = await db.from("teams").select("id,name").eq("organisation_id",organisationId).order("name").limit(100); return data?.length ? <ScopeSelector name="teamId" value={selection.teamId} label="Choose team" options={data.map((item) => ({ id:String(item.id),label:String(item.name) }))}/> : null; }
  return null;
}

export async function ProductionCoachingScreen({ organisationId, section, workspace, selection = {} }: { organisationId: string; section: string; workspace: string; selection?: { teamId?: string; matchId?: string; sessionId?: string } }) {
  const client = await createServerSupabaseClient();
  if (!client) throw new Error("The organisation connection is unavailable.");
  const db = client as unknown as SupabaseClient;
  const { data: authData } = await db.auth.getUser();
  if (!authData.user) throw new Error("Your authenticated session is unavailable.");

  if (["match-day", "formation", "playing-time"].includes(section)) {
    const { data: matchList, error: matchListError } = await db.from("matches").select("id,team_id,event_instance_id,state,created_at").eq("organisation_id", organisationId).order("created_at", { ascending: false }).limit(100);
    const { data: allMatchInstances, error: allMatchInstancesError } = await db.from("matches").select("event_instance_id").eq("organisation_id", organisationId).order("id").limit(5_000);
    const { data: selectedMatchData, error: selectedMatchError } = selection.matchId && selection.matchId !== "new" ? await db.from("matches").select("id,team_id,event_instance_id,state,created_at").eq("organisation_id", organisationId).eq("id", selection.matchId).maybeSingle() : { data: null, error: null };
    if (matchListError || allMatchInstancesError || selectedMatchError) throw new Error("We could not load match choices.");
    const existingInstanceIds = [...new Set((allMatchInstances ?? []).map((item) => String(item.event_instance_id)))];
    let eligibleMatchEventData: { id: unknown; team_id: unknown; starts_at: unknown; events: unknown }[] = [];
    let eligibleMatchTeamNames = new Map<string, string>();
    if (section === "match-day") {
      let eventQuery = db.from("event_instances").select("id,starts_at,team_id,events!inner(title,kind)").eq("organisation_id", organisationId).eq("events.kind", "match").eq("status", "scheduled").order("starts_at", { ascending: true }).limit(500);
      if (existingInstanceIds.length) eventQuery = eventQuery.not("id", "in", `(${existingInstanceIds.join(",")})`);
      const { data: eligibleEvents, error: eligibleError } = await eventQuery.limit(50);
      if (eligibleError) throw new Error("We could not load eligible match events.");
      eligibleMatchEventData = eligibleEvents ?? [];
      const eligibleTeamIds = [...new Set(eligibleMatchEventData.map((event) => String(event.team_id)))];
      const { data: eligibleTeams } = eligibleTeamIds.length ? await db.from("teams").select("id,name").eq("organisation_id", organisationId).in("id", eligibleTeamIds) : { data: [] };
      eligibleMatchTeamNames = new Map((eligibleTeams ?? []).map((team) => [String(team.id), String(team.name)]));
    }
    const eligibleMatchEvents: MatchEventOption[] = eligibleMatchEventData.map((event) => { const related = event.events as unknown as { title?: string } | null; return { id: String(event.id), title: `${eligibleMatchTeamNames.get(String(event.team_id)) ?? "Team"} · ${String(related?.title ?? "Match")}`, startsAt: String(event.starts_at) }; });
    if (section === "match-day" && selection.matchId === "new") return eligibleMatchEvents.length ? <MatchDayCreator events={eligibleMatchEvents} workspace={workspace} section={section} another/> : <EmptyState title="No eligible match event" description="Schedule another canonical match event before creating match day."/>;
    const selectedMatchId = selectedMatchData?.id ? String(selectedMatchData.id) : String(matchList?.[0]?.id ?? "");
    const { data, error } = await db.from("matches").select("id,team_id,event_instance_id,state,side_size,started_at,elapsed_before_ms,completed_at").eq("organisation_id", organisationId).eq("id", selectedMatchId).maybeSingle();
    if (error) throw new Error("We could not load match day.");
    const match = data as Row | null;
    if (!match) {
      if (section !== "match-day") return <EmptyState title="No match-day record yet" description="Create a match from a canonical match event before using formations and the match clock."/>;
      return <div className="space-y-5">{eligibleMatchEvents.length ? <MatchDayCreator events={eligibleMatchEvents} workspace={workspace} section={section}/> : <EmptyState title="No eligible match event" description="Schedule a canonical match event before creating match day."/>}</div>;
    }
    if (section === "formation") {
      const { data: formationData, error: formationError } = await db.from("formations").select("id,name,side_size,created_at").eq("organisation_id", organisationId).eq("match_id", match.id).order("created_at", { ascending: false }).limit(20);
      if (formationError) throw new Error("We could not load the formation.");
      const { players, source: participantSource } = await loadMatchPlayers(db, organisationId, String(match.event_instance_id), String(match.team_id));
      const sideSize = Number(match.side_size);
      return <div className="space-y-5">{String(match.state) === "ready" && players.length >= sideSize ? <section className={panel}><h2 className="text-xl font-semibold text-ink">Build a complete {sideSize}-a-side formation</h2><p className="mt-2 text-sm text-muted">{participantSource}: choose {sideSize} different players and exactly one goalkeeper. The complete shape is saved atomically.</p><form action={saveProductionFormation} className="mt-5 space-y-4"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><input type="hidden" name="sideSize" value={sideSize}/><label className="block text-sm font-semibold">Formation name<input className={field} name="name" defaultValue={`Match-day ${sideSize}`} required minLength={2}/></label>{Array.from({ length: sideSize }, (_, index) => <div className="grid gap-3 sm:grid-cols-2" key={index}><label className="text-sm font-semibold">Player {index + 1}<select className={field} name={`player${index}`}>{players.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Position<select className={field} name={`position${index}`} defaultValue={index === 0 ? "GK" : index === sideSize - 1 ? "ST" : "CB"}>{["GK","LB","CB","RB","LWB","RWB","DM","CM","AM","LW","RW","ST"].map((position) => <option key={position}>{position}</option>)}</select></label></div>)}<Button type="submit">Save complete formation</Button></form></section> : null}{formationData?.length ? <Records title="Saved match formations" rows={formationData as Row[]}/> : <EmptyState title="No complete formation" description={`Add a complete ${sideSize}-player formation with exactly one goalkeeper before starting the match.`}/>}</div>;
    }
    if (section === "playing-time") {
      const { data: timeData, error: timeError } = await db.from("playing_time_records").select("id,player_id,total_minutes,goalkeeper_minutes,starter_minutes,off_pitch_minutes,position_minutes,calculated_at").eq("organisation_id", organisationId).eq("match_id", match.id).order("total_minutes", { ascending: false }).limit(100);
      if (timeError) throw new Error("We could not load playing time.");
      const { data: intervalData, error: intervalError } = await db.from("match_position_intervals").select("player_id,position_code,entered_at,left_at").eq("organisation_id", organisationId).eq("match_id", match.id).limit(1_000);
      const { data: correctionData, error: correctionError } = await db.from("playing_time_corrections").select("id,player_id,adjustment_minutes,reason,created_at").eq("organisation_id",organisationId).eq("match_id",match.id).order("created_at",{ ascending:false }).limit(100);
      if (intervalError || correctionError) throw new Error("We could not load live playing time.");
      const { players } = await loadMatchPlayers(db, organisationId, String(match.event_instance_id), String(match.team_id));
      const playerLabels = new Map(players.map((player) => [player.id, player.label]));
      const liveIntervals = (intervalData ?? []).map((item) => ({ playerId:String(item.player_id),position:String(item.position_code),enteredAt:String(item.entered_at),leftAt:item.left_at?String(item.left_at):null }));
      const correctedTimeData = (timeData ?? []).map((record) => ({ ...record, player: playerLabels.get(String(record.player_id)) ?? "Player record", effective_total_minutes: Number(record.total_minutes)+(correctionData ?? []).filter((correction)=>correction.player_id===record.player_id).reduce((sum,correction)=>sum+Number(correction.adjustment_minutes),0) }));
      const labelledCorrections = (correctionData ?? []).map((correction) => ({ ...correction, player: playerLabels.get(String(correction.player_id)) ?? "Player record" }));
      return <div className="space-y-5">
        {String(match.state) !== "completed" ? <ProductionPlayingTimeTracker players={players} intervals={liveIntervals} state={String(match.state)} startedAt={typeof match.started_at === "string" ? match.started_at : null} elapsedBeforeMs={Number(match.elapsed_before_ms)}/> : null}
        {timeData?.length ? <><Records title="Calculated playing time" rows={correctedTimeData as Row[]} limit={8}/>{correctionData?.length ? <Records title="Audited playing-time correction history" rows={labelledCorrections as Row[]}/> : null}<section className={panel}><h2 className="text-xl font-semibold text-ink">Audited playing-time correction</h2><form action={recordProductionPlayingTimeCorrection} className="mt-5 grid gap-4 sm:grid-cols-3"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><label className="text-sm font-semibold">Player<select className={field} name="playerId">{players.map((player) => <option key={player.id} value={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Adjustment (minutes)<input className={field} type="number" step="0.1" name="adjustmentMinutes" required/></label><label className="text-sm font-semibold">Audit reason<input className={field} name="reason" minLength={5} required/></label><Button type="submit" className="sm:col-span-3">Record correction note</Button></form></section></> : <EmptyState title="Playing time is being tracked" description="Live interval totals appear above; final starter, off-pitch and position exposure are calculated at full time."/>}
      </div>;
    }
    const state = String(match.state);
    const nextStates = state === "ready" ? ["running"] : state === "running" ? ["paused", "completed"] : state === "paused" ? ["running", "completed"] : [];
    const { data: events, error: eventsError } = await db.from("match_events").select("id,player_id,event_type,occurred_at,elapsed_ms").eq("organisation_id", organisationId).eq("match_id", match.id).order("occurred_at", { ascending: false }).limit(20);
    if (eventsError) throw new Error("We could not load the match timeline.");
    const { players, source: participantSource } = await loadMatchPlayers(db, organisationId, String(match.event_instance_id), String(match.team_id));
    const { data: intervalData } = state === "running" ? await db.from("match_position_intervals").select("player_id,position_code").eq("organisation_id", organisationId).eq("match_id", match.id).is("left_at", null) : { data: [] };
    const labelById = new Map(players.map((player) => [player.id, player.label]));
    const onPitch = (intervalData ?? []).map((row) => ({ id: String(row.player_id), position: String(row.position_code), label: labelById.get(String(row.player_id)) ?? "Player" }));
    const onPitchIds = new Set(onPitch.map((player) => player.id));
    const bench = players.filter((player) => !onPitchIds.has(player.id));
    return <div className="space-y-5"><MatchDayCreator events={eligibleMatchEvents} workspace={workspace} section={section} another/><section className={panel}><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="text-xl font-semibold text-ink">Match controls</h2><Status tone={state === "running" ? "success" : state === "completed" ? "neutral" : "info"}>{state}</Status></div><p className="mt-2 text-sm text-muted">Participants: {participantSource}</p><ProductionMatchClock state={state} startedAt={typeof match.started_at === "string" ? match.started_at : null} elapsedBeforeMs={Number(match.elapsed_before_ms)}/><div className="mt-5 flex flex-wrap gap-3">{nextStates.map((next) => <form action={transitionProductionMatch} key={next}><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><input type="hidden" name="state" value={next}/><Button type="submit" variant={next === "completed" ? "secondary" : "primary"}>{next === "running" ? state === "paused" ? "Resume match" : "Start match" : next === "paused" ? "Pause match" : "Complete match"}</Button></form>)}</div>{state === "running" && players.length ? <><form action={recordProductionMatchEvent} className="mt-6 grid gap-4 sm:grid-cols-3"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><label className="text-sm font-semibold">Event<select className={field} name="eventType">{[["goal","Goal"],["assist","Assist"],["save","Save"],["card","Card"],["positive-moment","Positive moment"],["learning-moment","Learning moment"],["injury","Injury marker"]].map(([value,label]) => <option value={value} key={value}>{label}</option>)}</select></label><label className="text-sm font-semibold">Player<select className={field} name="playerId">{players.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><Button className="self-end" type="submit">Record event</Button></form>{onPitch.length && bench.length ? <form action={substituteProductionPlayer} className="mt-6 grid gap-4 sm:grid-cols-4"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><label className="text-sm font-semibold">Player off<select className={field} name="outgoingPlayerId">{onPitch.map((player) => <option value={player.id} key={player.id}>{player.label} · {player.position}</option>)}</select></label><label className="text-sm font-semibold">Player on<select className={field} name="incomingPlayerId">{bench.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Position<select className={field} name="position">{["GK","LB","CB","RB","LWB","RWB","DM","CM","AM","LW","RW","ST"].map((position) => <option key={position}>{position}</option>)}</select></label><Button className="self-end" type="submit">Make substitution</Button></form> : null}{onPitch.length > 1 ? <form action={rotateProductionPositions} className="mt-6 grid gap-4 sm:grid-cols-3"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><label className="text-sm font-semibold">First player<select className={field} name="firstPlayerId">{onPitch.map((player) => <option value={player.id} key={player.id}>{player.label} · {player.position}</option>)}</select></label><label className="text-sm font-semibold">Second player<select className={field} name="secondPlayerId">{onPitch.map((player) => <option value={player.id} key={player.id}>{player.label} · {player.position}</option>)}</select></label><Button className="self-end" type="submit">Rotate positions</Button></form> : null}</> : null}</section>{state === "completed" ? <section className={panel}><h2 className="text-xl font-semibold text-ink">Post-match reflection</h2><form action={saveProductionMatchReflection} className="mt-5 grid gap-4"><Context workspace={workspace} section={section}/><input type="hidden" name="matchId" value={String(match.id)}/><label className="text-sm font-semibold">Private coaching reflection<textarea className={`${field} min-h-28 py-3`} name="privateReflection" required/></label><label className="text-sm font-semibold">Positive parent update<textarea className={`${field} min-h-28 py-3`} name="parentSummary" required/></label><Button type="submit">Approve and share parent update</Button></form></section> : null}{events?.length ? <section className={panel}><h2 className="text-xl font-semibold text-ink">Audited match timeline</h2><ul className="mt-4 divide-y divide-border">{(events as Row[]).map((event) => <li className="flex flex-wrap items-center justify-between gap-3 py-3" key={String(event.id)}><span className="text-sm"><strong className="capitalize">{String(event.event_type).replaceAll("-", " ")}</strong> · {labelById.get(String(event.player_id)) ?? "Player record"} · {Math.floor(Number(event.elapsed_ms) / 60000)} min</span><form action={correctProductionMatchEvent} className="flex gap-2"><Context workspace={workspace} section={section}/><input type="hidden" name="eventId" value={String(event.id)}/><input className="min-h-10 rounded-[10px] border border-border-strong px-3" name="reason" placeholder="Correction reason" minLength={5} required/><Button type="submit" variant="secondary">Void with audit</Button></form></li>)}</ul></section> : null}</div>;
  }

  if (["training", "attendance"].includes(section)) {
    const { data, error } = await db.from("training_sessions").select("id,team_id,title,status,planned_duration_minutes,created_at").eq("organisation_id", organisationId).order("created_at", { ascending: false }).limit(10);
    const { data: selectedSessionData, error: selectedSessionError } = selection.sessionId ? await db.from("training_sessions").select("id,team_id,title,status,planned_duration_minutes,created_at").eq("organisation_id", organisationId).eq("id", selection.sessionId).maybeSingle() : { data: null, error: null };
    if (error || selectedSessionError) throw new Error("We could not load training sessions.");
    const sessions = selectedSessionData ? [selectedSessionData as Row, ...((data ?? []) as Row[]).filter((session) => session.id !== selectedSessionData.id)] : ((data ?? []) as Row[]);
    if (section === "training") {
      const { data: eventData, error: eventError } = await db.from("event_instances").select("id,team_id,starts_at,events!inner(title,kind)").eq("organisation_id", organisationId).eq("events.kind", "training").eq("status", "scheduled").order("starts_at").limit(20);
      const trainingTeamIds = [...new Set((eventData ?? []).map((event) => String(event.team_id)))];
      const { data: trainingTeams, error: trainingTeamsError } = trainingTeamIds.length ? await db.from("teams").select("id,name").eq("organisation_id", organisationId).in("id", trainingTeamIds) : { data: [], error: null };
      const { data: drillData, error: drillError } = await db.from("drills").select("id,title,duration_minutes").eq("organisation_id", organisationId).order("title").limit(250);
      const { data: templateData, error: templateError } = await db.from("training_templates").select("id,title,duration_minutes").eq("organisation_id", organisationId).order("title").limit(100);
      const templateIds = (templateData ?? []).map((item) => String(item.id));
      const { data: templateItemData } = templateIds.length ? await db.from("training_template_items").select("id,template_id,drill_id,title,duration_minutes,sort_order,participant_focus,equipment,area_description,setup,setup_diagram_url,instructions,coaching_points,progression,regression,safety_notes,inclusion_adaptations,goalkeeper_adaptation,coach_notes").eq("organisation_id", organisationId).in("template_id", templateIds) : { data: [] };
      const latestSessionId = sessions[0]?.id;
      const { data: segmentData } = latestSessionId ? await db.from("training_segments").select("id,title,duration_minutes,sort_order,participant_focus,equipment,area_description,setup,setup_diagram_url,instructions,coaching_points,progression,regression,safety_notes,inclusion_adaptations,goalkeeper_adaptation,coach_notes").eq("organisation_id", organisationId).eq("training_session_id", latestSessionId) : { data: [] };
      const { data: sessionDrillData } = latestSessionId ? await db.from("session_drills").select("id,drill_id,duration_minutes,sort_order,participant_focus,equipment,area_description,setup,setup_diagram_url,instructions,coaching_points,progression,regression,safety_notes,inclusion_adaptations,goalkeeper_adaptation,coach_notes,drills(title)").eq("organisation_id", organisationId).eq("training_session_id", latestSessionId) : { data: [] };
      const builderItems = [...(segmentData ?? []).map((item) => ({ key: String(item.id), kind: "segment" as const, title: String(item.title), drillId: "", durationMinutes: Number(item.duration_minutes), participantFocus: String(item.participant_focus ?? ""), equipment: Array.isArray(item.equipment) ? item.equipment.join(", ") : "", area: String(item.area_description ?? ""), setup: String(item.setup ?? ""), diagramUrl: String(item.setup_diagram_url ?? ""), instructions: String(item.instructions ?? ""), coachingPoints: String(item.coaching_points ?? ""), progression: String(item.progression ?? ""), regression: String(item.regression ?? ""), safety: String(item.safety_notes ?? ""), inclusion: String(item.inclusion_adaptations ?? ""), goalkeeper: String(item.goalkeeper_adaptation ?? ""), notes: String(item.coach_notes ?? ""), order: Number(item.sort_order) })), ...(sessionDrillData ?? []).map((item) => ({ key: String(item.id), kind: "drill" as const, title: "", drillId: String(item.drill_id), durationMinutes: Number(item.duration_minutes), participantFocus: String(item.participant_focus ?? ""), equipment: Array.isArray(item.equipment) ? item.equipment.join(", ") : "", area: String(item.area_description ?? ""), setup: String(item.setup ?? ""), diagramUrl: String(item.setup_diagram_url ?? ""), instructions: String(item.instructions ?? ""), coachingPoints: String(item.coaching_points ?? ""), progression: String(item.progression ?? ""), regression: String(item.regression ?? ""), safety: String(item.safety_notes ?? ""), inclusion: String(item.inclusion_adaptations ?? ""), goalkeeper: String(item.goalkeeper_adaptation ?? ""), notes: String(item.coach_notes ?? ""), order: Number(item.sort_order) }))].sort((a,b) => a.order - b.order);
      if (eventError || trainingTeamsError || drillError || templateError) throw new Error("We could not load training plan options.");
      const trainingTeamNames = new Map((trainingTeams ?? []).map((team) => [String(team.id), String(team.name)]));
      const eventOptions = (eventData ?? []).map((event) => { const related = event.events as unknown as { title?: string } | null; return { id: String(event.id), label: `${trainingTeamNames.get(String(event.team_id)) ?? "Team"} · ${String(related?.title ?? "Training")} · ${new Date(String(event.starts_at)).toLocaleString("en-GB")}` }; });
      const drillOptions = (drillData ?? []).map((drill) => ({ id: String(drill.id), label: String(drill.title) }));
      const templateOptions = (templateData ?? []).map((template) => ({ id: String(template.id), title: String(template.title), durationMinutes: Number(template.duration_minutes), items: (templateItemData ?? []).filter((item) => item.template_id === template.id).sort((a,b) => Number(a.sort_order) - Number(b.sort_order)).map((item) => ({ key: String(item.id), kind: item.drill_id ? "drill" as const : "segment" as const, title: String(item.title), drillId: String(item.drill_id ?? ""), durationMinutes: Number(item.duration_minutes), participantFocus: String(item.participant_focus ?? ""), equipment: Array.isArray(item.equipment) ? item.equipment.join(", ") : "", area: String(item.area_description ?? ""), setup: String(item.setup ?? ""), diagramUrl: String(item.setup_diagram_url ?? ""), instructions: String(item.instructions ?? ""), coachingPoints: String(item.coaching_points ?? ""), progression: String(item.progression ?? ""), regression: String(item.regression ?? ""), safety: String(item.safety_notes ?? ""), inclusion: String(item.inclusion_adaptations ?? ""), goalkeeper: String(item.goalkeeper_adaptation ?? ""), notes: String(item.coach_notes ?? "") })) }));
      return <div className="space-y-5"><section className={panel}><h2 className="text-xl font-semibold text-ink">Create a training plan</h2><p className="mt-2 text-sm text-muted">Add, reorder and remove full segments or drills, or copy a reusable template. Duration and ordering are checked atomically.</p>{eventOptions.length ? <ProductionTrainingBuilder workspace={workspace} section={section} events={eventOptions} drills={drillOptions} templates={templateOptions}/> : <p className="mt-4 text-sm text-muted">Create a canonical training event before planning this session.</p>}</section>{latestSessionId && builderItems.length ? <section className={panel}><h2 className="text-xl font-semibold text-ink">Edit the latest plan</h2><ProductionTrainingBuilder workspace={workspace} section={section} events={[]} drills={drillOptions} templates={templateOptions} sessionId={String(latestSessionId)} initialTitle={String(sessions[0]?.title ?? "Team training")} initialDuration={Number(sessions[0]?.planned_duration_minutes ?? 60)} initialItems={builderItems}/><form action={createProductionTrainingTemplate} className="mt-5 flex flex-wrap items-end gap-3"><Context workspace={workspace} section={section}/><input type="hidden" name="sessionId" value={String(latestSessionId)}/><label className="grow text-sm font-semibold">Template name<input className={field} name="templateTitle" required defaultValue="Reusable team session"/></label><Button type="submit">Save as template</Button></form></section> : null}{sessions.length ? <Records title="Production training plans" rows={sessions}/> : <EmptyState title="No training sessions yet" description="Create the first plan above."/>}</div>;
    }
    if (!sessions.length) return <EmptyState title="No training sessions yet" description="Create a training session from a canonical training event."/>;
    const session = sessions[0]!;
    const players = await loadTeamPlayers(db, organisationId, String(session.team_id));
    const { data: attendance, error: attendanceError } = await db.from("training_attendance").select("id,player_id,status,occurred_at,synced_at").eq("organisation_id", organisationId).eq("training_session_id", session.id).order("occurred_at", { ascending: false }).limit(250);
    const { data: guestAttendance, error: guestError } = await db.from("training_guest_attendance").select("id,attendee_label,status,occurred_at,synced_at").eq("organisation_id", organisationId).eq("training_session_id", session.id).order("occurred_at", { ascending: false }).limit(100);
    if (attendanceError || guestError) throw new Error("We could not load attendance.");
    return <div className="space-y-5"><section className={panel}><h2 className="text-xl font-semibold text-ink">Record attendance</h2><p className="mt-2 text-sm text-muted">Attendance is submitted directly over the authenticated connection and is never placed in a durable browser queue.</p><ProductionAttendanceRecorder organisationId={organisationId} sessionId={String(session.id)} players={players}/></section>{attendance?.length ? <Records title="Latest player attendance" rows={attendance as Row[]}/> : null}{guestAttendance?.length ? <Records title="Temporary and unexpected attendees" rows={guestAttendance as Row[]}/> : null}</div>;
  }

  if (section === "drills") {
    const { data, error } = await db.from("drills").select("id,title,objective,duration_minutes,difficulty,visibility,minimum_age,maximum_age").eq("organisation_id", organisationId).order("title").limit(250);
    if (error) throw new Error("We could not load the drill library.");
    return <div className="space-y-5"><section className={panel}><h2 className="text-xl font-semibold text-ink">Create a reusable drill</h2><form action={createProductionDrill} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><input type="hidden" name="organisationId" value={organisationId}/><label className="text-sm font-semibold">Title<input className={field} name="title" required/></label><label className="text-sm font-semibold">Objective<input className={field} name="objective" required/></label><label className="text-sm font-semibold sm:col-span-2">Instructions<textarea className={`${field} min-h-24 py-3`} name="instructions" required/></label><label className="text-sm font-semibold">Duration (minutes)<input className={field} type="number" min="1" max="180" name="durationMinutes" defaultValue="15" required/></label><label className="text-sm font-semibold">Difficulty<select className={field} name="difficulty"><option value="adaptable">Adaptable</option><option value="beginner">Beginner</option><option value="developing">Developing</option><option value="challenging">Challenging</option></select></label><label className="text-sm font-semibold">Minimum players<input className={field} type="number" min="1" max="40" name="minimumPlayers" defaultValue="4" required/></label><label className="text-sm font-semibold">Maximum players<input className={field} type="number" min="1" max="40" name="maximumPlayers"/></label><label className="text-sm font-semibold">Minimum age<input className={field} type="number" min="3" max="18" name="minimumAge"/></label><label className="text-sm font-semibold">Maximum age<input className={field} type="number" min="3" max="18" name="maximumAge"/></label><label className="text-sm font-semibold">Equipment (comma separated)<input className={field} name="equipment"/></label><label className="text-sm font-semibold">Area<input className={field} name="area" placeholder="20 × 15 metre grid"/></label><label className="text-sm font-semibold sm:col-span-2">Adaptations<textarea className={`${field} min-h-20 py-3`} name="adaptations"/></label><label className="text-sm font-semibold">Diagram URL<input className={field} name="diagramUrl" type="url"/></label><label className="text-sm font-semibold">Visibility<select className={field} name="visibility"><option value="organisation">Whole club</option><option value="private">Private</option></select></label><Button className="sm:col-span-2" type="submit">Add drill to library</Button></form></section>{data?.length ? <Records title="Club drill library" rows={data as Row[]}/> : <EmptyState title="No drills yet" description="Create the first reusable drill above."/>}</div>;
  }
  if (section === "players") {
    const teamQuery = db.from("teams").select("id,name").eq("organisation_id", organisationId).order("id").limit(100);
    const { data: teamData } = selection.teamId ? await teamQuery.eq("id",selection.teamId).maybeSingle() : await teamQuery.limit(1).maybeSingle();
    const players = teamData?.id ? await loadTeamPlayers(db, organisationId, String(teamData.id)) : [];
    const objectiveQuery = db.from("development_objectives").select("id,player_id,title,status,target_date").eq("organisation_id", organisationId).order("id").limit(500);
    const { data, error } = teamData?.id ? await objectiveQuery.eq("team_id", String(teamData.id)).limit(50) : { data: [], error: null };
    const { data: observationData } = teamData?.id ? await db.rpc("list_coach_observations", { requested_team_id: String(teamData.id), requested_reason: "Coach opened the player development workspace" }) : { data: [] };
    if (error) throw new Error("We could not load player development.");
    return <div className="space-y-5">
      {teamData?.id && players.length ? <>
        <section className={panel}><h2 className="text-xl font-semibold text-ink">Create a development objective</h2><form action={createProductionDevelopmentObjective} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><input type="hidden" name="teamId" value={String(teamData.id)}/><label className="text-sm font-semibold">Player<select className={field} name="playerId">{players.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Objective<input className={field} name="title" required/></label><label className="text-sm font-semibold">Target date<input className={field} name="targetDate" type="date"/></label><Button type="submit" className="self-end">Save objective</Button></form></section>
        <section className={panel}><h2 className="text-xl font-semibold text-ink">Add a structured coaching observation</h2><p className="mt-2 text-sm text-muted">Coach-only: never shown to guardians, cached offline or sent to AI.</p><form action={recordProductionObservation} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><input type="hidden" name="teamId" value={String(teamData.id)}/><label className="text-sm font-semibold">Player<select className={field} name="playerId">{players.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Observation<textarea className={`${field} min-h-24 py-3`} name="observation" required/></label>{[["context","Context"],["strength","Strength"],["emergingSkill","Emerging skill"],["opportunity","Opportunity"],["confidenceEngagement","Confidence and engagement"],["position","Position"],["nextAction","Next action"],["trainingTheme","Training theme"]].map(([name,label]) => <label className="text-sm font-semibold" key={name}>{label}<input className={field} name={name}/></label>)}<label className="text-sm font-semibold">Visibility<select className={field} name="visibility"><option value="private">Only me</option><option value="coaching-staff">Coaching staff</option></select></label><label className="text-sm font-semibold">Follow-up date<input className={field} name="followUpDate" type="date"/></label><Button type="submit" className="sm:col-span-2">Save structured observation</Button></form></section>
      </> : null}
      {observationData?.length ? <ObservationRecords rows={observationData as Row[]} players={players}/> : null}{data?.length ? <Records title="Player objectives" rows={data as Row[]}/> : <EmptyState title="No player objectives yet" description="Create the first scoped objective above."/>}
    </div>;
  }
  if (section === "development") {
    const teamQuery = db.from("teams").select("id,name").eq("organisation_id", organisationId).order("id").limit(100);
    const { data: teamData } = selection.teamId ? await teamQuery.eq("id",selection.teamId).maybeSingle() : await teamQuery.limit(1).maybeSingle();
    const players = teamData?.id ? await loadTeamPlayers(db, organisationId, String(teamData.id)) : [];
    const reviewQuery = db.from("development_reviews").select("id,player_id,team_id,status,reviewed_at,private_review").eq("organisation_id", organisationId).order("id").limit(500);
    const objectiveQuery = db.from("development_objectives").select("id,player_id,team_id,status").eq("organisation_id", organisationId).eq("status", "active").order("id").limit(500);
    const { data, error } = teamData?.id ? await reviewQuery.eq("team_id", String(teamData.id)).limit(50) : { data: [], error: null };
    const { data: objectiveData, error: objectiveError } = teamData?.id ? await objectiveQuery.eq("team_id", String(teamData.id)) : { data: [], error: null };
    if (error || objectiveError) throw new Error("We could not load development reviews.");
    return <div className="space-y-5">
      {teamData?.id && players.length ? <section className={panel}><h2 className="text-xl font-semibold text-ink">Create a private development review</h2><form action={createProductionDevelopmentReview} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><input type="hidden" name="teamId" value={String(teamData.id)}/><label className="text-sm font-semibold">Player<select className={field} name="playerId">{players.map((player) => <option value={player.id} key={player.id}>{player.label}</option>)}</select></label><label className="text-sm font-semibold">Private review<textarea className={`${field} min-h-28 py-3`} name="privateReview" required/></label><Button type="submit" className="sm:col-span-2">Save private review</Button></form></section> : null}
      {data?.filter((review) => review.status === "draft").map((review) => { const objective = objectiveData?.find((item) => item.player_id === review.player_id && item.team_id === review.team_id); return <section className={panel} key={String(review.id)}><h2 className="text-xl font-semibold text-ink">Approve a parent-safe summary</h2><p className="mt-2 text-sm text-muted">Private review text remains coach-only. Write a separate positive summary and approve it deliberately.</p><form action={approveProductionDevelopmentSummary} className="mt-5 grid gap-4 sm:grid-cols-2"><Context workspace={workspace} section={section}/><input type="hidden" name="reviewId" value={String(review.id)}/><label className="text-sm font-semibold sm:col-span-2">Parent summary<textarea className={`${field} min-h-28 py-3`} name="summary" required maxLength={1200}/></label><label className="text-sm font-semibold">Current themes (comma separated)<input className={field} name="currentThemes"/></label><label className="text-sm font-semibold">Suggested activities (comma separated)<input className={field} name="suggestedActivities"/></label><label className="text-sm font-semibold">Term review<textarea className={`${field} min-h-20 py-3`} name="termReview"/></label><label className="text-sm font-semibold">Attendance summary<textarea className={`${field} min-h-20 py-3`} name="attendanceSummary"/></label><Button className="sm:col-span-2" type="submit">Approve and publish summary</Button></form>{objective ? <ProductionAiSuggestion organisationId={organisationId} teamId={String(review.team_id)} objectiveId={String(objective.id)} reviewId={String(review.id)} workspace={workspace} section={section}/> : null}</section>; })}
      {data?.length ? <Records title="Private development reviews" rows={data as Row[]}/> : <EmptyState title="No development reviews yet" description="Create a private review above, then approve a separate parent-safe summary."/>}
    </div>;
  }

  const tableBySection: Record<string, { table: string; select: string; title: string }> = {};
  const source = tableBySection[section];
  if (source) {
    const { data, error } = await db.from(source.table).select(source.select).eq("organisation_id", organisationId).limit(50);
    if (error) throw new Error(`We could not load ${source.title.toLowerCase()}.`);
    return data?.length ? <Records title={source.title} rows={data as unknown as Row[]}/> : <EmptyState title={`No ${source.title.toLowerCase()} yet`} description="Create the first scoped record to continue."/>;
  }

  return <EmptyState title="No production records for this view" description="This route is connected to production access control; add the corresponding scoped team records to continue."/>;
}

export async function ProductionParentDevelopmentScreen({ organisationId }: { organisationId: string }) {
  const client = await createServerSupabaseClient();
  if (!client) throw new Error("The organisation connection is unavailable.");
  const db = client as unknown as SupabaseClient;
  const { data, error } = await db.from("parent_development_summaries").select("id,player_id,team_id,summary,current_themes,suggested_activities,term_review,attendance_summary,approved_at").eq("organisation_id", organisationId).order("approved_at", { ascending: false }).limit(100);
  const { data: matchData, error: matchError } = await db.from("parent_match_summaries").select("id,team_id,match_id,summary,approved_at").eq("organisation_id", organisationId).order("approved_at", { ascending: false }).limit(100);
  if (error || matchError) throw new Error("We could not load approved development updates.");
  const playerIds = [...new Set((data ?? []).map((item) => String(item.player_id)))]; const teamIds = [...new Set([...(data ?? []),...(matchData ?? [])].map((item) => String(item.team_id)))];
  const { data: players } = playerIds.length ? await db.from("players").select("id,first_name,last_name").eq("organisation_id",organisationId).in("id",playerIds) : { data: [] };
  const { data: teams } = teamIds.length ? await db.from("teams").select("id,name").eq("organisation_id",organisationId).in("id",teamIds) : { data: [] };
  const matchIds = (matchData ?? []).map((item) => String(item.match_id)); const { data: matches } = matchIds.length ? await db.from("matches").select("id,event_instance_id").eq("organisation_id",organisationId).in("id",matchIds) : { data: [] };
  const instanceIds = (matches ?? []).map((item) => String(item.event_instance_id)); const { data: instances } = instanceIds.length ? await db.from("event_instances").select("id,starts_at,event_id").eq("organisation_id",organisationId).in("id",instanceIds) : { data: [] };
  const eventIds = (instances ?? []).map((item) => String(item.event_id)); const { data: events } = eventIds.length ? await db.from("events").select("id,title").eq("organisation_id",organisationId).in("id",eventIds) : { data: [] };
  const teamName = (id: unknown) => String(teams?.find((item) => item.id === id)?.name ?? "Team");
  const developmentRows = (data ?? []).map((item) => ({ id: item.id, child: `${String(players?.find((player) => player.id === item.player_id)?.first_name ?? "Child")} ${String(players?.find((player) => player.id === item.player_id)?.last_name ?? "")}`.trim(), team: teamName(item.team_id), update: item.summary, current_themes: (item.current_themes ?? []).join(", "), suggested_activities: (item.suggested_activities ?? []).join(", "), term_review: item.term_review, attendance: item.attendance_summary, approved: item.approved_at }));
  const matchRows = (matchData ?? []).map((item) => { const matchRecord = matches?.find((match) => match.id === item.match_id); const instance = instances?.find((entry) => entry.id === matchRecord?.event_instance_id); return { id:item.id, team:teamName(item.team_id), match: String(events?.find((event) => event.id === instance?.event_id)?.title ?? "Match"), date: instance?.starts_at ? new Date(String(instance.starts_at)).toLocaleDateString("en-GB") : "—", update:item.summary, approved:item.approved_at }; });
  return <div className="space-y-5">{matchRows.length ? <Records title="Approved match updates" rows={matchRows} limit={6}/> : null}{developmentRows.length ? <Records title="Approved development updates" rows={developmentRows} limit={9}/> : null}{!developmentRows.length && !matchRows.length ? <EmptyState title="No approved updates" description="Only approved summaries for your linked children appear here."/> : null}</div>;
}
